using namespace std;

class Solution {
    const int MOD = 1e9 + 7;
    int dfs(int u, int n, const vector<vector<pair<int, int>>>& adj, const vector<int>& dist, vector<int>& memo) {
        if (u == n) return 1;
        if (memo[u] != -1) return memo[u];
        long long ans = 0;
        for (const auto& [v, w] : adj[u]) {
            if (dist[u] > dist[v]) {
                ans = (ans + dfs(v, n, adj, dist, memo)) % MOD;
            }
        }
        return memo[u] = ans;
    }

public:
    int countRestrictedPaths(int n, vector<vector<int>>& edges) {
        vector<vector<pair<int, int>>> adj(n + 1);
        for (const auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
            adj[e[1]].push_back({e[0], e[2]});
        }
        vector<int> dist(n + 1, 2e9);
        dist[n] = 0;
        using P = pair<int, int>;
        priority_queue<P, vector<P>, greater<P>> pq;
        pq.push({0, n});
        while (!pq.empty()) {
            auto [d, u] = pq.top();
            pq.pop();
            if (d > dist[u]) continue;
            for (const auto& [v, w] : adj[u]) {
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.push({dist[v], v});
                }
            }
        }
        vector<int> memo(n + 1, -1);
        return dfs(1, n, adj, dist, memo);
    }
};

import java.util.*;

class Solution {
    private final int MOD = 1_000_000_007;

    private int dfs(int u, int n, List<List<int[]>> adj, int[] dist, int[] memo) {
        if (u == n) return 1;
        if (memo[u] != -1) return memo[u];
        long ans = 0;
        for (int[] edge : adj.get(u)) {
            int v = edge[0];
            if (dist[u] > dist[v]) {
                ans = (ans + dfs(v, n, adj, dist, memo)) % MOD;
            }
        }
        return memo[u] = (int)ans;
    }

    public int countRestrictedPaths(int n, int[][] edges) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i <= n; ++i) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2]});
            adj.get(e[1]).add(new int[]{e[0], e[2]});
        }
        int[] dist = new int[n + 1];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[n] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        pq.offer(new int[]{0, n});
        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int d = curr[0], u = curr[1];
            if (d > dist[u]) continue;
            for (int[] edge : adj.get(u)) {
                int v = edge[0], w = edge[1];
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.offer(new int[]{dist[v], v});
                }
            }
        }
        int[] memo = new int[n + 1];
        Arrays.fill(memo, -1);
        return dfs(1, n, adj, dist, memo);
    }
}

