var countRestrictedPaths = function(n, edges) {
    const MOD = 1000000007;
    const adj = Array.from({ length: n + 1 }, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
    }

    const dist = Array(n + 1).fill(Infinity);
    dist[n] = 0;
    const pq = [[0, n]];

    const push = (item) => {
        pq.push(item);
        let idx = pq.length - 1;
        while (idx > 0) {
            const p = Math.floor((idx - 1) / 2);
            if (pq[p][0] > pq[idx][0]) {
                [pq[p], pq[idx]] = [pq[idx], pq[p]];
                idx = p;
            } else break;
        }
    };

    const pop = () => {
        if (pq.length === 0) return null;
        const top = pq[0];
        const last = pq.pop();
        if (pq.length > 0) {
            pq[0] = last;
            let idx = 0;
            while (true) {
                let left = 2 * idx + 1, right = 2 * idx + 2, smallest = idx;
                if (left < pq.length && pq[left][0] < pq[smallest][0]) smallest = left;
                if (right < pq.length && pq[right][0] < pq[smallest][0]) smallest = right;
                if (smallest !== idx) {
                    [pq[idx], pq[smallest]] = [pq[smallest], pq[idx]];
                    idx = smallest;
                } else break;
            }
        }
        return top;
    };

    while (pq.length > 0) {
        const [d, u] = pop();
        if (d > dist[u]) continue;
        for (const [v, w] of adj[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                push([dist[v], v]);
            }
        }
    }

    const memo = Array(n + 1).fill(-1);
    function dfs(u) {
        if (u === n) return 1;
        if (memo[u] !== -1) return memo[u];
        let ans = 0;
        for (const [v] of adj[u]) {
            if (dist[u] > dist[v]) {
                ans = (ans + dfs(v)) % MOD;
            }
        }
        return memo[u] = ans;
    }

    return dfs(1);
};
